def parse_ini(text: str) -> dict[str, dict[str, str]]:
    """
    Parse an INI file and return a dictionary of sections where each section is a dictionary of key-value pairs.
    """
    sections = {}
    current_section = None
    default_section = {}

    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith(('#', ';')):
            continue

        if line.startswith('[') and line.endswith(']'):
            section_name = line[1:-1].strip()
            if section_name == 'DEFAULT':
                current_section = None
            else:
                current_section = section_name
                sections[section_name] = default_section.copy()
        else:
            if current_section is None:
                raise ValueError("Key line before any section header")

            # Split the line into key and value
            split_index = min(line.find('='), line.find(':'))
            if split_index == -1:
                raise ValueError("Malformed line")
            key, value = line[:split_index].strip().lower(), line[split_index + 1:].strip()

            # Check for continuation
            if line.startswith(' '):
                if current_section not in sections or key not in sections[current_section]:
                    raise ValueError("Continuation line without previous key")
                value = sections[current_section][key] + '\n' + value
                sections[current_section][key] = value
            else:
                # Replace interpolation
                def replace_interpolation(value: str) -> str:
                    if '${' in value:
                        if value.startswith('${') and value.endswith('}'):
                            key = value[2:-1]
                            if ':' in key:
                                section, key = key.split(':')
                                if section not in sections:
                                    raise KeyError(f"Section '{section}' not found")
                                value = value.replace('${' + key + '}', sections[section][key])
                            else:
                                if current_section is None:
                                    raise KeyError(f"Key '{key}' not found in DEFAULT section")
                                value = value.replace('${' + key + '}', sections[current_section][key])
                        else:
                            raise ValueError("Invalid interpolation")
                    return value

                sections[current_section][key] = replace_interpolation(value)

    return sections
