from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.cache = OrderedDict()
        self.stats = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def put(self, key, value):
        current_time = self.clock()
        if key in self.cache:
            self.cache[key] = (current_time, value)
        else:
            if len(self.cache) >= self.capacity:
                self._remove_expired()
                if len(self.cache) >= self.capacity:
                    self._evict_lru()
            self.cache[key] = (current_time, value)

    def get(self, key, default=None):
        current_time = self.clock()
        if key in self.cache:
            value, expiry = self.cache[key]
            if current_time >= expiry:
                self.stats["expirations"] += 1
                del self.cache[key]
                return default
            else:
                self.cache[key] = (current_time, value)
                self.stats["hits"] += 1
                return value
        else:
            self.stats["misses"] += 1
            return default

    def __len__(self):
        return sum(1 for key, (time, _) in self.cache.items() if self.clock() < time + self.ttl)

    def stats(self):
        return self.stats.copy()

    def _remove_expired(self):
        current_time = self.clock()
        self.cache = OrderedDict((key, value) for key, (time, value) in self.cache.items() if current_time < time + self.ttl)

    def _evict_lru(self):
        self.cache.popitem(last=False)
        self.stats["evictions"] += 1
