def summarize_ranges(nums: list[int]) -> str:
    if not nums:
        return ""

    nums = sorted(set(nums))
    result = []
    start = nums[0]
    count = 1

    for i in range(1, len(nums)):
        if nums[i] == nums[i-1] + 1:
            count += 1
        else:
            if count >= 3:
                result.append(f"{start}..{nums[i-1]}")
            else:
                result.append(",".join(map(str, range(start, nums[i-1] + 1))))
            start = nums[i]
            count = 1

    if count >= 3:
        result.append(f"{start}..{nums[-1]}")
    else:
        result.append(",".join(map(str, range(start, nums[-1] + 1))))

    return ",".join(result)
